  imports=sorted(set(n.module if isinstance(n,ast.ImportFrom) else alias.name for n in ast.walk(tree) if isinstance(n,(ast.Import,ast.ImportFrom)) for alias in (n.names if isinstance(n,ast.Import) else [None]) if isinstance(n,ast.Import) or n.module))
